#!/bin/bash

# The entire skeleton of this file was generated by Gemini flash 3.8
# Prompt:
# bash script for scanner tests that compiles scanner_test.c + scanner.c
# and runs all .scala files through it with expected exit codes, expected files (diff),
# and expected output text checking

cd "$(dirname "$0")"

# --- Paths (adjust to match your folder structure) ---
SRC_DIR="../../src"
TEST_SRC="scanner_test.c"
BUILD_DIR="../../build"
BINARY="$BUILD_DIR/scanner_test"
LOG_DIR="../test_logs/scanner"

mkdir -p "$BUILD_DIR"
mkdir -p "$LOG_DIR"


# --- Run Tests ---
PASS="\e[32m✔ PASS\e[0m"
FAIL="\e[31m✘ FAIL\e[0m"

passed_count=0
failed_count=0

echo "============================================================"
echo "               RUNNING SCANNER TESTS"
echo -e "============================================================\n"

# Loop through every .scala file in ../
for file in ../*.scala; do
    [ -e "$file" ] || continue

    name=$(basename "$file" .scala)
    log_file="$LOG_DIR/$name.txt"

    # ==========================================================================
    # ==========================================================================
    # 🪟 THE OPEN WINDOW: TEST EXPECTATIONS
    # --------------------------------------------------------------------------
    # Settings:
    #   expected_exit   -> Exit code (0 for success, 1 for lexical error)
    #   expected_output -> Substring that must appear in stdout/stderr ("" to ignore)
    #   expected_file   -> Diffs against this file, fails on mismatch ("" to ignore)
    # ==========================================================================
    case "$name" in
        "tiny_prog"*)
            # Example: Scanner prints all scanned tokens, matched against expected dump
            expected_exit=0
            expected_output=""
            expected_file=""
            ;;

        *"small_prog"*)
            # Example: Expecting lexical error (exit code 1)
            expected_exit=0
            expected_output=""
            expected_file=""
            ;;

        "medium_prog"*)
            # Example: Expecting specific error exit code and error message substring
            expected_exit=0
            expected_output=""
            expected_file=""
            ;;

        *)
            # Default fallback for unlisted tests: expect clean exit code 0
            expected_exit=0
            expected_output=""
            expected_file=""
            ;;
    esac
    # ==========================================================================
    # ==========================================================================

    # Feed the .scala file to the scanner binary via stdin
    "$BINARY" < "$file" > "$log_file" 2>&1
    actual_exit=$?

    # --- Validate Results (Exit code -> Diff -> Grep) ---
    if [ $actual_exit -ne $expected_exit ]; then
        echo -e "  $FAIL   $name (Expected exit $expected_exit, got $actual_exit)"
        echo -e "           -> Log: $log_file\n"
        failed_count=$((failed_count + 1))

    elif [ -n "$expected_file" ] && ! diff -u "$expected_file" "$log_file" > /dev/null 2>&1; then
        echo -e "  $FAIL   $name (Output does not match $expected_file)"
        echo -e "           -> Diff command: diff -u $expected_file $log_file\n"
        failed_count=$((failed_count + 1))

    elif [ -n "$expected_output" ] && ! grep -q "$expected_output" "$log_file"; then
        echo -e "  $FAIL   $name (Missing expected text: '$expected_output')"
        echo -e "           -> Log: $log_file\n"
        failed_count=$((failed_count + 1))

    else
        echo -e "  $PASS   $name (Log: $log_file)"
        passed_count=$((passed_count + 1))
    fi

done

# --- Final Summary ---
total_count=$((passed_count + failed_count))

echo "------------------------------------------------------------"
echo "Summary: $passed_count passed, $failed_count failed ($total_count total)"
echo "============================================================"

# Return non-zero if any test failed so CI / Make stops
[ $failed_count -eq 0 ]
